-- 2026-11-07 — GPT-6 Pro ALAN 7 içerik bulguları (soru ve ders içeriği).
--
-- NİÇİN: GPT-6 Pro'nun soru/ders içeriği denetimi (alan 7) yanlış cevap
-- anahtarı, yanlış olgu, yanlış Kurmancî, anlam kayması ve cevabı ele veren
-- şık bulguları buldu. Yalnız sahibin içerik ilkesine uyan düzeltmeler
-- alındı: soru silinmedi/emekliye ayrılmadı, sorunun konusu değişmedi; her
-- (soru kimliği, alan) çifti için ≥2 bağımsız modelin (Gemini 3.8 Flash,
-- Gemini 4 Argon, Claude Sonnet 5.5) AYNI nihai metinde uyuşması şart
-- koşuldu (toplu bul-değiştir yok). Kayıt: ~/Projects/zankurd_kapisma/hazir/
-- alan7_oneri.tsv (öneri) ve alan7_karar.tsv (karar).
--
-- ETKİ: en çok 375 (id, sütun) hedefi (170 yerel kimlikli soru alanı, 205
-- yalnız sunucu sorusu alanı) ve 9 ders slaytı metni. Sunucu metni
-- bu dosyanın yazıldığı sırada CANLIDAN OKUNMADI; her hedef eski metne
-- bağlıdır: değer eskisinden farklıysa o SORUNUN hiçbir hedefi uygulanmaz
-- ('atla'), böylece sonradan değişmiş satırın üstüne yazılmaz ve soru yarım
-- düzeltilmez. Yerel kimlikler uuid5(ad alanı, "zankurd-local:" + yerel id).
-- Şık metinleri sunucuda farklı sırada olabileceğinden, bir şık hedefi eski
-- metni dört şıktan TAM BİR tanesinde bulur ve o sütunu günceller;
-- correct_option hiçbir satırda değişmez (sonda doğrulanır).
-- Türkçe soru kökü/şık alanları (promptTr, answersTr...) sunucuda tutulmaz;
-- onlar yalnız uygulama paketindedir.
--
-- GERİ ALMA: geri_al/2026-11-07_icerik_alan7_geri.sql — aynı sabit liste,
-- yeni → eski; değeri ne eski ne yeni olan alanda durur.
-- Uygulama: supabase db query --linked -f supabase/2026-11-07_icerik_alan7.sql

begin;

create temp table _hedef (
  id uuid, yerel text, sutun text, eski text, yeni text, kaynak text,
  durum text, gercek_sutun text, onceki_dogru text
) on commit drop;

-- Aynı (id, sütun) iki kez hedeflenmesin (şıklar eski metinle ayrılır).
do $$ begin
  if exists (select 1 from _hedef where sutun <> 'sik' group by id, sutun having count(*) > 1)
     or exists (select 1 from _hedef where sutun = 'sik' group by id, eski having count(*) > 1) then
    raise exception 'alan7: ayni hedef birden cok kez';
  end if;
end $$;

-- Hedef satırları kilitle.
select 1 from questions where id in (select id from _hedef) for update;

create or replace function pg_temp.deger(q questions, s text) returns text language sql immutable as $f$
  select case s when 'explanation' then q.explanation when 'explanation_ku' then q.explanation_ku
    when 'explanation_tr' then q.explanation_tr when 'option_a' then q.option_a when 'option_b' then q.option_b
    when 'option_c' then q.option_c when 'option_d' then q.option_d when 'prompt' then q.prompt end $f$;

-- Ön sınıflama: uygula / zaten / yok / farkli; bir sorunun herhangi bir hedefi
-- 'farkli' ise sorunun kalan hedefleri 'atla' (yarım düzeltme yok).
update _hedef h set durum = 'yok' where not exists (select 1 from questions q where q.id = h.id);
update _hedef h set onceki_dogru = q.correct_option from questions q where q.id = h.id;
update _hedef h set durum = 'uygula', gercek_sutun = h.sutun from questions q
 where q.id = h.id and h.sutun <> 'sik' and pg_temp.deger(q, h.sutun) is not distinct from h.eski;
update _hedef h set durum = 'zaten', gercek_sutun = h.sutun from questions q
 where q.id = h.id and h.durum is null and h.sutun <> 'sik' and pg_temp.deger(q, h.sutun) is not distinct from h.yeni;
update _hedef h set durum = 'uygula',
  gercek_sutun = (select s from questions q, unnest(array['option_a','option_b','option_c','option_d']) s
                  where q.id = h.id and pg_temp.deger(q, s) = h.eski)
 where h.sutun = 'sik' and h.durum is null and exists (select 1 from questions q where q.id = h.id and
   (select count(*) from unnest(array[q.option_a,q.option_b,q.option_c,q.option_d]) v where v = h.eski) = 1);
update _hedef h set durum = 'zaten', gercek_sutun = x.s
  from (select h2.id, h2.eski, (select s from questions q, unnest(array['option_a','option_b','option_c','option_d']) s
                  where q.id = h2.id and pg_temp.deger(q, s) = h2.yeni limit 1) s from _hedef h2) x
 where h.sutun = 'sik' and h.durum is null and x.id = h.id and x.eski = h.eski and x.s is not null;
update _hedef set durum = 'farkli' where durum is null;
update _hedef set durum = 'atla'
 where durum = 'uygula' and id in (select id from _hedef where durum = 'farkli');

do $$
declare r record;
begin
  for r in select durum, count(*) n from _hedef group by durum order by durum loop
    raise notice 'alan7 on siniflama: % = %', r.durum, r.n;
  end loop;
end $$;

-- Güncelleme (yalnız değer hâlâ eskiyse; tam bir satır etkilenmeli).
do $$
declare r record; n int; toplam int := 0; beklenen int;
begin
  select count(*) into beklenen from _hedef where durum = 'uygula';
  for r in select * from _hedef where durum = 'uygula' loop
    execute format('update questions set %I = $1 where id = $2 and %I is not distinct from $3',
                   r.gercek_sutun, r.gercek_sutun) using r.yeni, r.id, r.eski;
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'alan7: % % guncellenemedi', r.yerel, r.gercek_sutun; end if;
    toplam := toplam + n;
  end loop;
  if toplam <> beklenen then
    raise exception 'alan7: etkilenen % <> beklenen %', toplam, beklenen;
  end if;
end $$;

do $$
declare n int;
begin
  select count(*) into n from _hedef h join questions q on q.id = h.id
   where h.durum = 'uygula' and pg_temp.deger(q, h.gercek_sutun) is distinct from h.yeni;
  if n > 0 then raise exception 'alan7: % alan yeni degerde degil', n; end if;
  select count(*) into n from _hedef h join questions q on q.id = h.id
   where h.durum = 'uygula' and q.correct_option is distinct from h.onceki_dogru;
  if n > 0 then raise exception 'alan7: correct_option degisti (% satir)', n; end if;
end $$;

-- Ders slaytları: metin parçası (eski) slaytta TAM BİR kez geçmeli.
create temp table _ders (
  slug text, ord int, sutun text, eski text, yeni text, etiket text, durum text
) on commit drop;

do $$
declare r record; n int; uygulanan int := 0; beklenen int;
begin
  for r in select * from _ders loop
    select count(*) into n from lesson_slides ls join lessons l on l.id = ls.lesson_id
     where l.slug = r.slug and ls.order_in_lesson = r.ord
       and case r.sutun when 'content_ku' then ls.content_ku else ls.content_tr end is not null
       and (length(case r.sutun when 'content_ku' then ls.content_ku else ls.content_tr end)
            - length(replace(case r.sutun when 'content_ku' then ls.content_ku else ls.content_tr end, r.eski, '')))
           = length(r.eski);
    update _ders set durum = case when n = 1 then 'uygula' else 'atla' end
     where etiket = r.etiket and sutun = r.sutun and eski = r.eski;
  end loop;
  select count(*) into beklenen from _ders where durum = 'uygula';
  raise notice 'alan7 ders: uygula = %, atla = %', beklenen, (select count(*) from _ders where durum = 'atla');
  for r in select * from _ders where durum = 'uygula' loop
    if r.sutun = 'content_ku' then
      update lesson_slides ls set content_ku = replace(ls.content_ku, r.eski, r.yeni)
        from lessons l where ls.lesson_id = l.id and l.slug = r.slug and ls.order_in_lesson = r.ord;
    else
      update lesson_slides ls set content_tr = replace(ls.content_tr, r.eski, r.yeni)
        from lessons l where ls.lesson_id = l.id and l.slug = r.slug and ls.order_in_lesson = r.ord;
    end if;
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'alan7: ders % %/% guncellenemedi', r.etiket, r.slug, r.ord; end if;
    uygulanan := uygulanan + n;
  end loop;
  if uygulanan <> beklenen then
    raise exception 'alan7: ders etkilenen % <> beklenen %', uygulanan, beklenen;
  end if;
end $$;


-- Yinelenen soruların YENİDEN YAZIMI (sahip kararı: soru silinmez/emekliye
-- ayrılmaz; ikinci ve sonraki kimlik AYNI konuda FARKLI bir olguyu sorar).
-- Her satır tek bir sorunun (id) tamamıdır: kök, dört şık, açıklamalar.
-- Koşul: kök eskisiyle aynı, doğru şıkkın (correct_option harfi) metni eskisi
-- ve dört şıkkın kümesi eskinin kümesiyle aynı; biri farklıysa soru atlanır.
-- Doğru şık sunucudaki HARFİNDE kalır, üç yeni yanlış şık öteki harflere sırayla
-- yazılır; correct_option değişmez (sonda doğrulanır).
create temp table _yeniden (
  id uuid, yerel text, eski_kok text, eski_dogru text,
  e1 text, e2 text, e3 text, e4 text,
  yeni_kok text, yeni_dogru text, y1 text, y2 text, y3 text,
  yeni_ac text, yeni_ac_ku text, yeni_ac_tr text,
  eski_ac text, eski_ac_ku text, eski_ac_tr text, durum text
) on commit drop;
  yeni_ac, yeni_ac_ku, yeni_ac_tr, eski_ac, eski_ac_ku, eski_ac_tr) values
  ('52c9b4d5-4ce1-5fd8-9f22-ad162ff4d381','hat_0011','Berhema klasîk a bi navê "Mem û Zîn" ku bingeha romana kurdî tê dîtin, kê nivîsiye?','Ehmedê Xanî','Ehmedê Xanî','Feqiyê Teyran','Melayê Cizîrî','Elîyê Herîrî','Bûyerên berhema klasîk a "Mem û Zîn"ê ya Ehmedê Xanî li kîjan bajarî derbas dibin?','Cizîr','Bedlîs','Mêrdîn','Wan','"Mem û Zîn" destanındaki olaylar Cizre''de (Cizîra Botan), Mir Zeyneddin''in hükümdarlığı döneminde geçmektedir.','Bûyerên destana "Mem û Zîn"ê li bajarê Cizîrê (Cizîra Botan), di bin desthilatdariya Mîr Zeynedîn de derbas dibin.','"Mem û Zîn" destanındaki olaylar Cizre''de (Cizîra Botan), Mir Zeyneddin''in hükümdarlığı döneminde geçmektedir.','Bu eser 1692 yılında mesnevi biçiminde yazılmıştır ve 2655 beyitten oluşur.','Ev berhem di sala 1692yan de bi mesnewî hatiye nivîsîn û ji 2655 malikan pêk tê.','Bu eser 1692 yılında mesnevi biçiminde yazılmıştır ve 2655 beyitten oluşur.'),
  ('de7496bc-19ae-52c2-932d-92d4d73c5407','hat_0025','Nivîskarê berhema navdar "Mem û Zîn" kî ye?','Ehmedê Xanî','Ehmedê Xanî','Melayê Cizîrî','Feqiyê Teyran','Elî Herîrî','Berhema navdar a Ehmedê Xanî "Mem û Zîn" bi kîjan teşeya helbesta klasîk hatiye nivîsandin?','Mesnewî','Qesîde','Xezel','Rubaî','"Mem û Zîn", her beyti kendi arasında kafiyeli olan ve uzun anlatılar için kullanılan mesnevi nazım biçimiyle kaleme alınmıştır.','"Mem û Zîn" bi teşeya mesnewiyê hatiye nivîsandin ku her malikeke wê di nav xwe de bi serwa ye û ji bo çîrokên dirêj tê bikaranîn.','"Mem û Zîn", her beyti kendi arasında kafiyeli olan ve uzun anlatılar için kullanılan mesnevi nazım biçimiyle kaleme alınmıştır.','Bu eser 1692 yılında uzun bir mesnevi olarak yazılmış ve Kurmancî edebiyatının simgesi olmuştur.','Ev berhem di sala 1692an de wekî mesnewiyeke dirêj hatiye nivîsîn û bûye sembola edebiyata Kurmancî.','Bu eser 1692 yılında uzun bir mesnevi olarak yazılmış ve Kurmancî edebiyatının simgesi olmuştur.'),
  ('af74e5cf-95a7-536f-917a-1efd6387837b','bilim_0025','Nivîskarê Mem û Zînê ku ji berhemên klasîk ên edebiyata Kurmancî ye kî ye?','Ehmedê Xanî','Şerefxanê Bedlîsî','Celadet Alî Bedirxan','Mela Mehmûdê Bazîdî','Ehmedê Xanî','Kîjan berhema Ehmedê Xanî li ser bingehên bawerî û kelama îslamî bi awayê menzûm hatiye nivîsandin?','Eqîdeya Îmanê','Nehcul Enam','Mewlûda Nebî','Şêxê Senan','"Eqîdeya Îmanê", Ehmedê Xanî''nin İslam inanç esaslarını ve kelami konuları Kurmancî ile açıkladığı manzum eseridir.','"Eqîdeya Îmanê" berhema Ehmedê Xanî ya menzûm e ku tê de rêgezên baweriya îslamî û mijarên kelamî bi kurmancî hatine ravekirin.','"Eqîdeya Îmanê", Ehmedê Xanî''nin İslam inanç esaslarını ve kelami konuları Kurmancî ile açıkladığı manzum eseridir.','Mem û Zîn, Ehmedê Xanî''nin en tanınmış eseridir ve klasik Kürt edebiyatının başlıca yapıtları arasında yer alır.','Mem û Zîn berhema herî naskirî ya Ehmedê Xanî ye û di nav berhemên sereke yên edebiyata kurdî ya klasîk de cih digire.','Mem û Zîn, Ehmedê Xanî''nin en tanınmış eseridir ve klasik Kürt edebiyatının başlıca yapıtları arasında yer alır.'),
  ('a8d1e156-93e2-5df8-9342-6da44d298083','hat_0009','Kîjan nivîskarê kurd romana bi navê "Şivanê Kurmancan" nivîsiye, ku wek yekem romana kurmancî tê qebûlkirin?','Erebê Şemo','Mehmed Uzun','Erebê Şemo','Jan Dost','Hesenê Metê','Romana "Şivanê Kurmanca" ya Erebê Şemo di sala 1935an de li kîjan bajarî hatiye çapkirin?','Yêrêvan','Şam','Bexda','Qahîre','Erebê Şemo''nun "Şivanê Kurmanca" adlı romanı 1935 yılında Ermenistan''ın başkenti Erivan''da Devlet Yayınevi tarafından basılmıştır.','Romana "Şivanê Kurmanca" ya Erebê Şemo di sala 1935an de li paytexta Ermenistanê Yêrêvanê (Rewanê) ji aliyê Weşanxaneya Dewletê ve hatiye çapkirin.','Erebê Şemo''nun "Şivanê Kurmanca" adlı romanı 1935 yılında Ermenistan''ın başkenti Erivan''da Devlet Yayınevi tarafından basılmıştır.','Bu roman 1935 yılında Ermenistan''da yayımlanmıştır ve Sovyet Yezidilerinin yaşamını anlatır.','Ev roman di sala 1935an de li Ermenistanê hatiye weşandin û jiyana êzîdiyên Sovyetê vedibêje.','Bu roman 1935 yılında Ermenistan''da yayımlanmıştır ve Sovyet Yezidilerinin yaşamını anlatır.'),
  ('2bdc636f-6d2d-5c3f-9c94-0ad8d4b585a4','hat_0012','Romana bi navê "Tu" ku di sala 1985an de li Swêdê hatiye weşandin, kê nivîsiye?','Mehmed Uzun','Mehmed Uzun','Jan Dost','Hesenê Metê','Helîm Yûsiv','Mehmed Uzun romana xwe ya yekem a bi navê "Tu" di sala 1985an de li kîjan welatê ku lê nefî bû weşand?','Swêd','Fransa','Almanya','Belçîka','Mehmed Uzun ilk romanı "Tu"yu 1985 yılında İsveç''te (Stockholm) Orfeus Yayınları aracılığıyla yayımlamıştır.','Mehmed Uzun romana xwe ya yekem "Tu" di sala 1985an de li Swêdê (Stockholmê) di nav weşanên Orfeusê de da çapkirin.','Mehmed Uzun ilk romanı "Tu"yu 1985 yılında İsveç''te (Stockholm) Orfeus Yayınları aracılığıyla yayımlamıştır.','Mehmed Uzun 1977 yılında İsveç''e gitti ve bu romanı 1985''te orada Kurmancî yayımladı.','Mehmed Uzun di sala 1977an de çû Swêdê û ev roman di sala 1985an de li wir bi kurmancî weşand.','Mehmed Uzun 1977 yılında İsveç''e gitti ve bu romanı 1985''te orada Kurmancî yayımladı.'),
  ('517d07e4-b30c-5776-ac1f-18ed04d8ed63','hat_0010','Romana bi navê "Janî Gel" ku wek yekem romana soranî tê qebûlkirin, kê nivîsiye?','Îbrahîm Ehmed','Îbrahîm Ehmed','Bextiyar Elî','Ata Nahayî','Şêrzad Hesen','Nivîskarê romana "Janî Gel" Îbrahîm Ehmed di navbera salên 1939 û 1949an de kîjan kovara edebî ya navdar derxistiye?','Gelawêj','Hawar','Ronahî','Nûdem','Îbrahîm Ehmed, Alaaddin Secadi ile birlikte 1939-1949 yılları arasında modern Kürt edebiyatının gelişiminde temel bir yere sahip olan "Gelawêj" dergisini çıkarmıştır.','Îbrahîm Ehmed digel Elaedîn Secadî di navbera salên 1939 û 1949an de kovara "Gelawêj" derxistiye ku di pêşketina edebiyata kurdî ya nûjen de xwedî cihekî bingehîn e.','Îbrahîm Ehmed, Alaaddin Secadi ile birlikte 1939-1949 yılları arasında modern Kürt edebiyatının gelişiminde temel bir yere sahip olan "Gelawêj" dergisini çıkarmıştır.','Bu roman 1972 yılında yayımlanmıştır ve 1960''larda Kürtlerin siyasi mücadelesini anlatır.','Ev roman di sala 1972yan de hatiye weşandin û têkoşîna siyasî ya kurdan di salên 1960an de vedibêje.','Bu roman 1972 yılında yayımlanmıştır ve 1960''larda Kürtlerin siyasi mücadelesini anlatır.'),
  ('bbc34777-495f-5cf4-a329-55b7ebd24a86','hat_0015','Romana bi navê "Şarî Mûsîqare Spîyekan" ku di sala 2006an de hatiye weşandin, kê nivîsiye?','Bextiyar Elî','Bextiyar Elî','Ata Nahayî','Şêrzad Hesen','Jan Dost','Nivîskarê romana "Şarî Mûsîqare Spîyekan" Bextiyar Elî di sala 2017an de li Almanyayê xelata edebiyatê ya li ser navê kîjan helbestvanî wergirt?','Nelly Sachs','Georg Büchner','Heinrich Böll','Paul Celan','Bextiyar Elî, 2017 yılında Almanya''nın Dortmund kentinde Nelly Sachs Edebiyat Ödülü''ne layık görüldü ve bu ödülü alan ilk Kürt yazar oldu.','Bextiyar Elî di sala 2017an de li bajarê Dortmundê yê Almanyayê Xelata Edebiyatê ya Nelly Sachs wergirt û bû yekem nivîskarê kurd ê xwediyê vê xelatê.','Bextiyar Elî, 2017 yılında Almanya''nın Dortmund kentinde Nelly Sachs Edebiyat Ödülü''ne layık görüldü ve bu ödülü alan ilk Kürt yazar oldu.','Bu roman alegoriktir ve Soranî adı beyaz müzisyenler kenti anlamına gelir.','Ev roman alegorîk e û navê wê yê soranî tê wateya bajarê muzîkjenên spî.','Bu roman alegoriktir ve Soranî adı beyaz müzisyenler kenti anlamına gelir.'),
  ('672e9e72-58b5-56ce-a45f-3aca1f4cd1a2','hat_0028','Kîjan berhem ferhengeke bi helbest e û ji bo zarokan hatiye amadekirin?','Nûbihara Biçûkan','Dîwan','Zembîlfiroş','Şêxê Senan','Nûbihara Biçûkan','Ehmedê Xanî ferhenga xwe ya menzûm "Nûbihara Biçûkan" ji bo ku zarokên kurd bi hêsanî fêrî kîjan zimanî bibin nivîsandiye?','Erebî','Farisî','Tirkî','Suryanî','"Nûbihara Biçûkan", Ehmedê Xanî''nin 1683 yılında medrese öğrencisi çocukların Arapçayı öğrenmeleri amacıyla yazdığı manzum bir Arapça-Kürtçe sözlüktür.','"Nûbihara Biçûkan" ferhengeke erebî-kurdî ya menzûm e ku Ehmedê Xanî di sala 1683yan de ji bo zarokên medreseyan nivîsandiye da ku fêrî erebî bibin.','"Nûbihara Biçûkan", Ehmedê Xanî''nin 1683 yılında medrese öğrencisi çocukların Arapçayı öğrenmeleri amacıyla yazdığı manzum bir Arapça-Kürtçe sözlüktür.','Bu eser Arapça-Kurmancî bir sözlüktür ve "Mem û Zîn"in yazarı tarafından kaleme alınmıştır.','Ev berhem ferhengeke Erebî-Kurmancî ye û ji aliyê xwediyê "Mem û Zîn"ê ve hatiye nivîsîn.','Bu eser Arapça-Kurmancî bir sözlüktür ve "Mem û Zîn"in yazarı tarafından kaleme alınmıştır.'),
  ('9e7d0993-c7da-5025-9088-99ff19faf3d9','hat_0032','"Mem û Zîn" bi kîjan zaravayê hatiye nivîsîn?','Kurmancî','Soranî','Kurmancî','Zazakî','Hewramî','Di berhema "Mem û Zîn"ê de her du evîndar cara yekem di şahiya kîjan cejna kevneşopî de hev dibînin û gustîlan diguherînin?','Newroz','Gaxand','Kosegelî','Çille','Ehmedê Xanî''nin "Mem û Zîn" eserinde Mem ile Tacdîn ve Zîn ile Sîtî, Newroz şenliğinde kılık değiştirmiş halde karşılaşır, birbirlerine âşık olur ve yüzüklerini değiştirirler.','Di "Mem û Zîn"a Ehmedê Xanî de Mem û Tacdîn û Zîn û Sîtî di şahiya Newrozê de bi cilên guherî rastî hev tên, dil berdidin hev û gustîlên xwe diguherînin.','Ehmedê Xanî''nin "Mem û Zîn" eserinde Mem ile Tacdîn ve Zîn ile Sîtî, Newroz şenliğinde kılık değiştirmiş halde karşılaşır, birbirlerine âşık olur ve yüzüklerini değiştirirler.','Yazarı, Kürtlerin kendi dilleriyle okuyup yazması için bilinçli olarak bu lehçeyi seçmiştir.','Nivîskarê wê bi zanebûn ev zarava hilbijartiye da ku kurd bi zimanê xwe bixwînin û binivîsin.','Yazarı, Kürtlerin kendi dilleriyle okuyup yazması için bilinçli olarak bu lehçeyi seçmiştir.'),
  ('6d708587-697b-525d-856d-c78aa0e3eec1','ex28_dastangotin_007','Destana Zembîlfiroş a menzûm ji aliyê kîjan helbestvanê klasîk ve hatiye nivîsandin?','Feqiyê Teyran','Feqiyê Teyran','Ehmedê Xanî','Melayê Cizîrî','Elî Herîrî','Bûyerên destana "Zembîlfiroş" bi giranî li kîjan bajarokê dîrokî derbas dibin ku birca bi heman navî îro jî li wir e?','Farqîn','Xelat','Amêdî','Heskîf','"Zembîlfiroş" destanındaki olaylar Silvan''da (Farqîn) geçmektedir ve Zembîlfiroş Burcu tarihi bir kalıntı olarak bugün de Silvan ilçesinde yer almaktadır.','Bûyerên destana "Zembîlfiroş" li Farqînê (Silîvanê) derbas dibin û Birca Zembîlfiroş wekî bermahiyeke dîrokî îro jî li navçeya Farqînê ye.','"Zembîlfiroş" destanındaki olaylar Silvan''da (Farqîn) geçmektedir ve Zembîlfiroş Burcu tarihi bir kalıntı olarak bugün de Silvan ilçesinde yer almaktadır.','Zembîlfiroş, klasik Kurmancî şair Feqiyê Teyran''ın mesnevisidir; eser onun adıyla bilinir.','Zembîlfiroş mesnewiyeke Feqiyê Teyran e; ew helbestvanekî klasîk ê kurmancî ye û ev destan bi navê wî tê naskirin.','Zembîlfiroş, klasik Kurmancî şair Feqiyê Teyran''ın mesnevisidir; eser onun adıyla bilinir.'),
  ('e8346c3c-7f18-54b2-9e1c-0d9fbd0a76f6','hat_0045','Fîlma Yilmaz Guney û Şerîf Goren a bi navê Yol di kîjan salê de li Cannesê xelata sereke wergirt?','1982','1982','1979','1985','1988','Ji ber ku senarîstê fîlmê "Yol" Yilmaz Guney di girtîgehê de bû, derhêneriya fîlmî li ser setê kê pêk anî?','Şerîf Goren','Zekî Okten','Atif Yilmaz','Erden Kiral','"Yol" filminin senaryosu Yılmaz Güney tarafından cezaevinde yazılmış, çekimleri ise onun talimatları doğrultusunda Şerif Gören tarafından gerçekleştirilmiştir.','Senaryoya fîlmê "Yol" ji aliyê Yilmaz Guney ve di girtîgehê de hatiye nivîsandin û Şerîf Goren li gorî talîmatên wî fîlm li ser setê kişandiye.','"Yol" filminin senaryosu Yılmaz Güney tarafından cezaevinde yazılmış, çekimleri ise onun talimatları doğrultusunda Şerif Gören tarafından gerçekleştirilmiştir.','Yol, Cannes''da Altın Palmiye''yi Costa-Gavras''ın Missing filmiyle paylaştı.','Yol li Cannesê Palmiyeya Zêrîn bi fîlma Missing a Costa-Gavras re parve kir.','Yol, Cannes''da Altın Palmiye''yi Costa-Gavras''ın Missing filmiyle paylaştı.'),
  ('d7964afe-76dd-52f6-b4c1-6a558ca50c95','hat_0056','Kê fîlmê Min Dît ê sala 2009an derhênerî kir?','Miraz Bezar','Miraz Bezar','Kazim Oz','Hiner Saleem','Bahman Ghobadi','Çîroka her du zarokên sêwî Gulîstan û Firat di fîlmê "Min Dît" ê sala 2009an de li kîjan bajarî derbas dibe?','Amed','Hewlêr','Qamişlo','Mahabad','"Min Dît" filmi Diyarbakır''da çekilmiştir ve anne babalarının öldürülmesinin ardından Diyarbakır sokaklarında yaşam mücadelesi veren iki kardeşin öyküsünü anlatır.','Fîlmê "Min Dît" li Amedê hatiye kişandin û çîroka du xwişk û birayên ku piştî kuştina dê û bavê xwe li kolanên Amedê têkoşîna jiyanê didin vedibêje.','"Min Dît" filmi Diyarbakır''da çekilmiştir ve anne babalarının öldürülmesinin ardından Diyarbakır sokaklarında yaşam mücadelesi veren iki kardeşin öyküsünü anlatır.','Film, Diyarbakır''da anne ve babasını kaybettikten sonra sokakta kalan iki çocuğun hikayesini anlatır.','Fîlm çîroka du zarokên li Diyarbekirê vedibêje ku piştî windakirina dê û bavê xwe li kolanan dimînin.','Film, Diyarbakır''da anne ve babasını kaybettikten sonra sokakta kalan iki çocuğun hikayesini anlatır.'),
  ('0df9117c-e4e0-58fa-8cec-56678b1cae2e','ex28_yilmaz_guney_002','Yilmaz Guney li gundekî ser bi kîjan bajarî ve ji dayik bû?','Adana','Adana','Hatay','Dîlok','Mêrsîn','Derhêner û lîstikvan Yilmaz Guney di sala 1984an de li kîjan bajarî koça dawî kir?','Parîs','Berlîn','London','Roma','Yılmaz Güney, 9 Eylül 1984 tarihinde Fransa''nın başkenti Paris''te hayatını kaybetti ve Père Lachaise Mezarlığı''na defnedildi.','Yilmaz Guney di 9ê Îlona 1984an de li Parîsa paytexta Fransayê koça dawî kir û li Goristana Père Lachaise hate veşartin.','Yılmaz Güney, 9 Eylül 1984 tarihinde Fransa''nın başkenti Paris''te hayatını kaybetti ve Père Lachaise Mezarlığı''na defnedildi.','Yılmaz Güney 1 Nisan 1937''de Adana''nın bugünkü Yüreğir ilçesine bağlı Yenice köyünde doğdu.','Yilmaz Guney di 1ê Nîsana 1937an de li gundê Yeniceyê yê Adanayê ji dayik bû; ew gund niha ser bi navçeya Yüreğirê ve ye.','Yılmaz Güney 1 Nisan 1937''de Adana''nın bugünkü Yüreğir ilçesine bağlı Yenice köyünde doğdu.'),
  ('2184ca8c-877e-5e87-9754-b935ab960572','ex28_yilmaz_guney_003','Gel bi kîjan nasnavî gazî Yilmaz Guney dikir?','Çirkin Kral','Aslan Yürek','Deli Yusuf','Çirkin Kral','Kara Şahin','Paşnavê Yilmaz Guney ê rastîn di nasnameyê de çi bû?','Pûtûn','Kaya','Polat','Baran','Yılmaz Güney''in resmi adı Yılmaz Pütün''dür; kendi ifadesiyle "pütün", kırılması zor sert yabani meyve çekirdeği anlamına gelir.','Navê Yilmaz Guney ê fermî Yilmaz Pûtûn e; li gorî gotina wî "pûtûn" tê wateya dendikê fêkiyên kovî yê hişk ku nayê şikandin.','Yılmaz Güney''in resmi adı Yılmaz Pütün''dür; kendi ifadesiyle "pütün", kırılması zor sert yabani meyve çekirdeği anlamına gelir.','Bu lakap, Yılmaz Atadeniz''in yönettiği ve Güney''in başrolde oynadığı 1966 yapımı "Çirkin Kral" filminden gelir.','Ev nasnav ji fîlmê "Çirkin Kral" (1966) hat, ku Yılmaz Atadeniz kişandibû û Yilmaz Guney tê de rola sereke lîstibû.','Bu lakap, Yılmaz Atadeniz''in yönettiği ve Güney''in başrolde oynadığı 1966 yapımı "Çirkin Kral" filminden gelir.'),
  ('b24b10db-f383-5b47-a5c2-afe8c253d20e','hat_0074','Kîjan çiya bi bilindahiya xwe ya nêzî 5137 metreyan çiyayê herî bilind ê herêmê tê naskirin?','Agirî','Sîpan','Cûdî','Nemrûd','Agirî','Girseya Çiyayê Agiriyê ji bilî parêzgeha Agiriyê di nav sînorên kîjan parêzgehê de cih digire?','Îdir','Mûş','Bedlîs','Çewlîg','Ağrı Dağı kütlesinin kuzey ve doğudaki büyük bir bölümü Iğdır ili sınırları içinde, diğer bölümü ise Ağrı ili sınırları içinde yer alır.','Beşeke mezin a girseya Çiyayê Agiriyê li bakur û rojhilat dikeve nav sînorên parêzgeha Îdirê û beşa din jî di nav sînorên Agiriyê de ye.','Ağrı Dağı kütlesinin kuzey ve doğudaki büyük bir bölümü Iğdır ili sınırları içinde, diğer bölümü ise Ağrı ili sınırları içinde yer alır.','Ağrı Dağı Türkiye, Ermenistan ve İran sınırları yakınındadır ve zirvesi yıl boyu karla kaplıdır.','Agirî li Tirkiyeyê ye, nêzî sînorên Ermenistan û Îranê ye û lûtkeya wî her tim bi berfê girtî ye.','Ağrı Dağı Türkiye, Ermenistan ve İran sınırları yakınındadır ve zirvesi yıl boyu karla kaplıdır.'),
  ('4104e723-e929-5fec-8304-5461e2bbd213','hat_0076','Kîjan gol û bendav li parêzgeha Silêmaniyê ye û li ser Zapê Biçûk hatiye çêkirin?','Dukan','Dukan','Wan','Hazar','Çildir','Çemê Zapê Biçûk ê ku Bendava Dukanê li ser hatiye avakirin, milê kîjan çemê mezin e?','Dîcle','Firat','Aras','Çoruh','Küçük Zap Suyu, İran topraklarından doğup Süleymaniye ilinden geçerek Dicle Nehri''ne katılan önemli bir koldur.','Zapê Biçûk ji Rojhilatê Kurdistanê derdikeve, di parêzgeha Silêmaniyê re derbas dibe û tevlî Çemê Dîcleyê dibe.','Küçük Zap Suyu, İran topraklarından doğup Süleymaniye ilinden geçerek Dicle Nehri''ne katılan önemli bir koldur.','Dukan Barajı 1950''lerde yapılmıştır, elektrik ve sulama için kullanılır ve turistik bir yerdir.','Bendava Dukanê di salên 1950yan de hatiye çêkirin, ji bo elektrîk û avdaniyê tê bikaranîn û cihekî geştyarî ye.','Dukan Barajı 1950''lerde yapılmıştır, elektrik ve sulama için kullanılır ve turistik bir yerdir.'),
  ('051f4790-3a84-5fe9-9ca5-40ce84c0b02e','hat_0114','Kîjan kes di nav damezrînerên Yekîtiya Niştimanî ya Kurdistanê de bû?','Celal Talebanî','Celal Talebanî','Mesûd Barzanî','Qazî Mihemed','Şêx Seîd','Serokê Giştî yê Yekîtiya Niştimanî ya Kurdistanê (YNK) Celal Talebanî di navbera salên 2005 û 2014an de li Iraqê kîjan erka fermî pêk anî?','Serokkomarî','Serokwezîrî','Serokatiya Dadgeha Bilind','Wezîriya Parastinê','Celal Talabani, 2005 yılında Irak''ın Arap olmayan ilk cumhurbaşkanı seçilmiş ve bu görevi 2014 yılına kadar sürdürmüştür.','Celal Talebanî di sala 2005an de wekî yekemîn serokkomarê ne-ereb ê Iraqê hate hilbijartin û heta sala 2014an ev erk domand.','Celal Talabani, 2005 yılında Irak''ın Arap olmayan ilk cumhurbaşkanı seçilmiş ve bu görevi 2014 yılına kadar sürdürmüştür.','Bu parti 1975''te Şam''da kuruldu ve Kürdistan Demokrat Partisinin başlıca rakibi oldu.','Ev partî di sala 1975an de li Şamê hat damezrandin û bû reqîbê sereke yê Partiya Demokrat a Kurdistanê.','Bu parti 1975''te Şam''da kuruldu ve Kürdistan Demokrat Partisinin başlıca rakibi oldu.'),
  ('d2eab631-2085-5baf-bb22-372b40ac61c5','ex28_nujen_015','Koma Wetan, yekem grûpa rockê ya kurdî, li kîjan bajarî hate damezrandin?','Tiflîs','Tiflîs','Yêrêvan','Mosko','Bakû','Damezrîner, solîst û gîtarîstê Koma Wetan a ku di dîroka muzîka rockê ya kurdî de cîhekî girîng digire kî ye?','Keremê Gerdenzerî','Aram Tîgran','Karapetê Xaço','Şivan Perwer','Koma Wetan, 1973 yılında müzisyen Keremê Gerdenzerî öncülüğünde kurulmuş ve 1979''da "Bayê Payîzê" albümünü kaydetmiştir.','Koma Wetan di sala 1973an de bi pêşengiya muzîkjen Keremê Gerdenzerî hat avakirin û di sala 1979an de albûma "Bayê Payîzê" tomar kir.','Koma Wetan, 1973 yılında müzisyen Keremê Gerdenzerî öncülüğünde kurulmuş ve 1979''da "Bayê Payîzê" albümünü kaydetmiştir.','Koma Wetan, o dönem Sovyetler Birliği''ne bağlı Gürcistan''ın başkenti Tiflis''te dört genç tarafından kuruldu. Grup, Kafkasyalı Kürt şairlerin şiirlerini rock müziğe uyarladı.','Koma Wetan li Tiflîsê, paytexta Gurcistana Sovyetê ya wê demê, ji aliyê çar ciwanan ve hate avakirin. Wan helbestên helbestvanên kurd ên Qefqasyayê bi muzîka rockê kirin stran.','Koma Wetan, o dönem Sovyetler Birliği''ne bağlı Gürcistan''ın başkenti Tiflis''te dört genç tarafından kuruldu. Grup, Kafkasyalı Kürt şairlerin şiirlerini rock müziğe uyarladı.'),
  ('2bf9fe3f-bc37-572c-8913-6887f0cc760c','ds_sinema_0086','Kîjan derhênerê japonî fîlma "Rashomon" derxist?','Akira Kurosawa','Kenji Mizoguchi','Yasujirō Ozu','Akira Kurosawa','Masaki Kobayashi','Fîlmê Akira Kurosawa yê bi navê "Rashomon" di sala 1951an de li kîjan festîvala navneteweyî xelata mezin a "Şêrê Zêrîn" wergirt?','Venedîk','Cannes','Berlîn','Locarno','"Rashomon" filmi, 1951 Venedik Film Festivali''nde Altın Aslan ödülünü kazanarak Japon sinemasının dünya çapında tanınmasını sağladı.','Fîlmê "Rashomon" di sala 1951an de li Festîvala Fîlman a Venedîkê xelata Şêrê Zêrîn wergirt û sînemaya japonî bi cîhanê da nasîn.','"Rashomon" filmi, 1951 Venedik Film Festivali''nde Altın Aslan ödülünü kazanarak Japon sinemasının dünya çapında tanınmasını sağladı.','Akira Kurosawa, 1950''de gösterime giren bu filmin yönetmenidir ve Japon sinemasını dünyaya tanıtmıştır.','Akira Kurosawa derhênerê vî fîlmî ye ku di sala 1950î de derket û sînemaya japonî bi cîhanê da nasîn.','Akira Kurosawa, 1950''de gösterime giren bu filmin yönetmenidir ve Japon sinemasını dünyaya tanıtmıştır.'),
  ('23ffc49d-0c65-514a-befc-deb74ef214cc','hat_0110','Komara Mehabadê di kîjan salê de hatiye ragihandin?','1946','1946','1932','1925','1958','Serokkomarê Komara Mehabadê ya ku di sala 1946an de hate ragihandin kî bû?','Qazî Mihemed','Şêx Mehmûdê Berzencî','Îhsan Nûrî Paşa','Simkoyê Şikak','Kadı Muhammed, 22 Ocak 1946''da Çarçıra Meydanı''nda ilan edilen Mahabad Cumhuriyeti''nin kurucusu ve cumhurbaşkanıydı.','Pêşewa Qazî Mihemed damezrîner û serokkomarê Komara Mehabadê bû ku di 22yê Çileya 1946an de li Meydana Çarçirayê hate ragihandin.','Kadı Muhammed, 22 Ocak 1946''da Çarçıra Meydanı''nda ilan edilen Mahabad Cumhuriyeti''nin kurucusu ve cumhurbaşkanıydı.','Cumhuriyetin merkezi Mahabad kentiydi ve yaklaşık bir yıl sonra sona erdi.','Navenda komarê bajarê Mehabadê bû û piştî nêzî salekê bi dawî bû.','Cumhuriyetin merkezi Mahabad kentiydi ve yaklaşık bir yıl sonra sona erdi.'),
  ('f1a7938f-c2a6-5ae0-b10e-d26cb691b272','kolay_dirok_11','Şerê Cîhanê yê Duyem kengî bi dawî bû?','1945','1945','1960','1939','1918','Şerê Cîhanê yê Duyem li Ewropayê di 1ê Îlona 1939an de bi êrîşa Almanyayê ya li ser kîjan welatî dest pê kir?','Polonya','Spanya','Swêd','Portûgal','İkinci Dünya Savaşı, 1 Eylül 1939 tarihinde Nazi Almanyası''nın Polonya''ya saldırmasıyla resmen başlamıştır.','Şerê Cîhanê yê Duyem di 1ê Îlona 1939an de dema ku Almanyaya Nazî êrîşî Polonyayê kir bi awayekî fermî dest pê kir.','İkinci Dünya Savaşı, 1 Eylül 1939 tarihinde Nazi Almanyası''nın Polonya''ya saldırmasıyla resmen başlamıştır.','İkinci Dünya Savaşı 1945''te sona erdi.','Şerê Cîhanê yê Duyem di sala 1945an de bi dawî bû.','İkinci Dünya Savaşı 1945''te sona erdi.'),
  ('6672c419-da36-5d37-bf4c-1b501947452a','kolay_dirok_17','Şerê Cîhanê yê Yekem kengî dest pê kir?','1914','1900','1914','1939','1923','Şerê Cîhanê yê Yekem di kîjan salê de bi dawî bû?','1918','1912','1923','1939','1914 yılında başlayan Birinci Dünya Savaşı, 11 Kasım 1918 tarihinde imzalanan ateşkesle sona ermiştir.','Şerê Cîhanê yê Yekem ê ku di sala 1914an de dest pê kiribû, di 11ê Çiriya Paşîn a 1918an de bi agirbestê bi dawî bû.','1914 yılında başlayan Birinci Dünya Savaşı, 11 Kasım 1918 tarihinde imzalanan ateşkesle sona ermiştir.','Birinci Dünya Savaşı 1914''te başladı.','Şerê Cîhanê yê Yekem di sala 1914an de dest pê kir.','Birinci Dünya Savaşı 1914''te başladı.'),
  ('729e4073-06f5-56b3-8c06-5a10adb6f4f0','ds_dirok_0031','Hawar ji bilî kovarê, di warê çi de jî girîng bû?','Alfabeya Kurdî','Çandina genim','Avakirina rêyan','Alfabeya Kurdî','Çêkirina çekan','Hejmara yekem a kovara Hawarê di 15ê Gulana 1932an de li kîjan bajarî hate weşandin?','Şam','Qahîre','Bexda','Bêrût','Hawar dergisi 15 Mayıs 1932''de Şam''da yayımlanmaya başlamış olup bu tarih Kürt Dil Bayramı olarak kutlanmaktadır.','Kovara Hawarê di 15ê Gulana 1932an de li bajarê Şamê dest bi weşanê kir û ev roj wekî Cejna Zimanê Kurdî tê pîrozkirin.','Hawar dergisi 15 Mayıs 1932''de Şam''da yayımlanmaya başlamış olup bu tarih Kürt Dil Bayramı olarak kutlanmaktadır.','Hawar, Celadet Alî Bedirxan''ın geliştirdiği Latin Kürt alfabesinin kabulünde temel bir rol oynadı. Dergi bu alfabeyi yaydı.','Hawar ji bo pejirandina alfabeya Latînî ya Kurdî ya ku Celadet Alî Bedirxan pêşve bir, roleke bingehîn lîst. Kovar vê alfabeyê belav kir.','Hawar, Celadet Alî Bedirxan''ın geliştirdiği Latin Kürt alfabesinin kabulünde temel bir rol oynadı. Dergi bu alfabeyi yaydı.'),
  ('fabfe9ba-7d82-5f8c-a144-bbace9e49090','ds_dirok_0043','Hawar ji bo kîjan alfabeyê wek çavkaniya sereke tê zanîn?','Alfabeya Latînî ya Kurdî','Alfabeya Erebî ya Kurdî','Alfabeya Latînî ya Kurdî','Alfabeya Kirîlî ya Kurdî','Alfabeya Tirkî','Kovara Hawarê ji aliyê kîjan rewşenbîr û zimanzanê kurd ve hate derxistin?','Celadet Elî Bedirxan','Cegerxwîn','Erebê Şemo','Qanatê Kurdo','Hawar dergisi Celadet Ali Bedirhan öncülüğünde çıkarılmış ve Latin harfli Kürt alfabesi ile dilbilgisinin temelini oluşturmuştur.','Kovara Hawarê bi pêşengiya Celadet Elî Bedirxan hate weşandin û bingeha rêziman û alfabeya kurdî ya latînî danî.','Hawar dergisi Celadet Ali Bedirhan öncülüğünde çıkarılmış ve Latin harfli Kürt alfabesi ile dilbilgisinin temelini oluşturmuştur.','Hawar, Kürtçe Latin alfabesinin yayılması için ana kaynak olarak bilinir. Bu alfabe Celadet Ali Bedirhan tarafından geliştirilmiştir.','Hawar ji bo belavkirina alfabeya Latînî ya Kurdî wek çavkaniya sereke tê zanîn. Ev alfabe ji aliyê Celadet Alî Bedirxan ve hate pêşve xistin.','Hawar, Kürtçe Latin alfabesinin yayılması için ana kaynak olarak bilinir. Bu alfabe Celadet Ali Bedirhan tarafından geliştirilmiştir.'),
  ('c5eb7ffc-9d1a-5b47-8080-f570a9dcde6f','ds_dirok_0143','Hejmara yekem a rojnameya Kurdistanê di kîjan salê de derket?','1898','1898','1908','1920','1940','Hejmara yekem a rojnameya "Kurdistan"ê di sala 1898an de li Qahîreyê ji aliyê kê ve hate derxistin?','Mîqdad Mîdhet Bedirxan','Pîremêrd','Huznî Mukriyanî','Memdûh Selîm','"Kurdistan" gazetesi, 22 Nisan 1898 tarihinde Kahire''de Mikdad Midhat Bedirhan tarafından yayımlanmaya başlamıştır.','Rojnameya "Kurdistan"ê di 22yê Nîsana 1898an de li Qahîreyê ji aliyê Mîqdad Mîdhet Bedirxan ve hate weşandin.','"Kurdistan" gazetesi, 22 Nisan 1898 tarihinde Kahire''de Mikdad Midhat Bedirhan tarafından yayımlanmaya başlamıştır.','Kurdistan gazetesinin ilk sayısı 22 Nisan 1898''de Kahire''de çıktı; yayın 1902''ye kadar 31 sayı sürdü.','Hejmara yekem a rojnameya Kurdistanê di 22ê Nîsana 1898an de li Qahîreyê derket.','Kurdistan gazetesinin ilk sayısı 22 Nisan 1898''de Kahire''de çıktı; yayın 1902''ye kadar 31 sayı sürdü.'),
  ('6cad65e9-1f45-5017-b588-7e7eda9a42f0','ds_muzik_0106','Di muzîkê de, leza ku bi piranî bi "beats per minute" tê pîvandin çi ye?','Tempo','Rîtm','Aheng','Melodî','Tempo','Di muzîkê de, amûra ku bi lêdanên birêkûpêk leza parçeyekî dipîve û rêberiyê ji muzîkjenan re dike çi ye?','Metronom','Diyapazon','Amplîfîkator','Mîkser','Metronom, müzisyenlerin doğru hızı koruması için dakikada belirli sayıda düzenli vuruş üreten mekanik veya elektronik bir alettir.','Metronom amûreke mekanîkî yan elektronîk e ku di deqîqeyê de bi hejmareke diyarkirî lêdanan derdixe da ku muzîkjen leza rast biparêzin.','Metronom, müzisyenlerin doğru hızı koruması için dakikada belirli sayıda düzenli vuruş üreten mekanik veya elektronik bir alettir.','Tempo müzikte müziğin hızıdır ve çoğunlukla "dakikadaki vuruş" ile ölçülür. Ritim seslerin dizilişidir, armoni seslerin uyumudur ve melodi de seslerin dizisidir.','Tempo di muzîkê de leza muzîkê ye û bi piranî bi "beats per minute" tê pîvandin. Rîtm rêjdana dengan e, aheng hevahengiya dengan e û melodî jî rêzika dengan e.','Tempo müzikte müziğin hızıdır ve çoğunlukla "dakikadaki vuruş" ile ölçülür. Ritim seslerin dizilişidir, armoni seslerin uyumudur ve melodi de seslerin dizisidir.'),
  ('7c32ea79-e7cd-5d95-8d9f-28990bc41ff4','ds_muzik_0103','Di muzîkê de, rêzkirina dengan li gorî demê çi ye?','Rîtm','Rîtm','Nota','Navber','Aheng','Di muzîkê de, nîşana nivîskî ya ku bilindahî û dirêjahiya dengekî diyar dike çi ye?','Nota','Porte','Gam','Oktav','Nota, müzik seslerinin yüksekliğini ve sürelerini porte üzerinde göstermek için kullanılan yazılı işaretlerdir.','Nota nîşanên nivîskî ne ku ji bo diyarkirina bilindahî û dirêjahiya dengan li ser porteyê tên bikaranîn.','Nota, müzik seslerinin yüksekliğini ve sürelerini porte üzerinde göstermek için kullanılan yazılı işaretlerdir.','Ritim müzikte seslerin zamana göre dizilişidir. Nota seslerin işaretidir, aralık sesler arasındaki mesafedir ve armoni de seslerin uyumudur.','Rîtm di muzîkê de rêjdana dengan li gorî demê ye. Nota nîşaneya dengan e, navber dûrahiya di navbera dengan de ye û aheng jî hevahengiya dengan e.','Ritim müzikte seslerin zamana göre dizilişidir. Nota seslerin işaretidir, aralık sesler arasındaki mesafedir ve armoni de seslerin uyumudur.'),
  ('14b96820-a3a1-566e-8144-1385d4707eb6','ds_muzik_0213','Kîjan têgîn ji bo nîşankirina hevahengiya dengan tê bikaranîn?','Armonî','Rîtm','Tempo','Armonî','Nota','Di muzîkê de, koma dengan a ku bi lêdana herî kêm sê dengên cuda di heman demê de pêk tê çi ye?','Akor','Solo','Melodî','Nakarat','Akor, farklı yükseklikteki en az üç notanın aynı anda tınlamasıyla oluşur ve müzikte armoninin temelini oluşturur.','Akor ji lêdana herî kêm sê notayên bi bilindahiyên cuda di heman demê de pêk tê û bingeha armoniyê ava dike.','Akor, farklı yükseklikteki en az üç notanın aynı anda tınlamasıyla oluşur ve müzikte armoninin temelini oluşturur.','Armoni, seslerin uyumunu belirtmek için kullanılır. Ritim zamanı, tempo hızı ve nota da yüksekliği gösterir.','Armonî ji bo nîşankirina hevahengiya dengan tê bikaranîn. Rîtm demê, tempo lezê û nota jî bilindahiyê nîşan dide.','Armoni, seslerin uyumunu belirtmek için kullanılır. Ritim zamanı, tempo hızı ve nota da yüksekliği gösterir.'),
  ('ef1c3cc5-9b90-5aa4-8847-ad79b1c5b2ba','ds_sinema_0109','Kîjan têgeha sînemayê ji bo pêvajoya hilbijartina wêneyan û lihevxistina wan ji bo çêkirina fîlmekî tê bikaranîn?','Montaj','Kadraj','Senaryo','Montaj','Diyalog','Di sînemayê de, metna nivîskî ya ku çîrok, dîmen û axaftinên fîlmekî bi hûrgilî dihewîne çi ye?','Senaryo','Kadraj','Dekor','Fragman','Senaryo, bir filmin tüm sahnelerinin, karakter hareketlerinin ve diyaloglarının yer aldığı yazılı metindir.','Senaryo nexşerêya nivîskî ya fîlmekî ye ku hemû dîmen, tevger û axaftinên karakteran tê de tên nivîsandin.','Senaryo, bir filmin tüm sahnelerinin, karakter hareketlerinin ve diyaloglarının yer aldığı yazılı metindir.','Montaj (kurgu), bir film oluşturmak için görüntüleri seçme, kesme ve birleştirme sürecidir. Bu süreç filmin ritmini ve hikaye anlatımını kontrol etmek için önemlidir. Kadraj görülen görüntüdür, senaryo hikayedir, diyalog ise konuşmadır.','Montaj (editing) pêvajoya hilbijartina wêneyan, birîna wan û lihevxistina wan e ji bo çêkirina fîlmekî. Ev pêvajo ji bo kontrolkirina rîtm û çîrokbêjiya fîlmê girîng e. Kadraj wêneyê ku tê dîtin e, senaryo çîrok e, diyalog jî axaftin e.','Montaj (kurgu), bir film oluşturmak için görüntüleri seçme, kesme ve birleştirme sürecidir. Bu süreç filmin ritmini ve hikaye anlatımını kontrol etmek için önemlidir. Kadraj görülen görüntüdür, senaryo hikayedir, diyalog ise konuşmadır.'),
  ('a9fdd114-645c-5abd-b5c8-43e75a36d221','ds_teknoloji_0242','Kîjan peyk ji bo destnîşankirina cihê rast ê li ser rûyê Erdê ji bo rêveçûna otomobîlan tê bikaranîn?','Peyka GPSê','Peyka ragihandinê','Peyka GPSê','Peyka meteorolojîk','Peyka keşfê','Kîjan cureyê peykê ji bo şopandina rewşa hewayê, ewran û bahozên li ser rûyê Erdê tê bikaranîn?','Peyka meteorolojîk','Peyka ragihandinê','Peyka navîgasyonê','Peyka astronomiyê','Meteoroloji uyduları uzaydan bulut hareketlerini, sıcaklıkları ve fırtınaları izleyerek hava tahmini için veri sağlar.','Peykên meteorolojîk ji fezayê tevgera ewran, germahî û bahozan dişopînin û ji bo pêşbîniya rewşa hewayê daneyan dişînin.','Meteoroloji uyduları uzaydan bulut hareketlerini, sıcaklıkları ve fırtınaları izleyerek hava tahmini için veri sağlar.','GPS uyduları, otomobillerin, uçakların ve gemilerin navigasyonu için Dünya yüzeyindeki kesin konumu belirlemek amacıyla kullanılır. İletişim, meteoroloji ve keşif uyduları ise başka amaçlar için kullanılır.','Peykên GPSê ji bo destnîşankirina cihê rast li ser rûyê Erdê ji bo rêveçûna otomobîlan, balafiran û keştiyan têne bikaranîn. Peykên ragihandinê, meteorolojîk û keşfê ji bo armancên din têne bikaranîn.','GPS uyduları, otomobillerin, uçakların ve gemilerin navigasyonu için Dünya yüzeyindeki kesin konumu belirlemek amacıyla kullanılır. İletişim, meteoroloji ve keşif uyduları ise başka amaçlar için kullanılır.'),
  ('b1c2bdfa-e22f-5144-a4c9-095202cd38fb','ds_teknoloji_0068','Di bernamekirinê de, kîjan têgeh ji bo hilanîna nirxekî ku dikare bibe rast an derew tê bikaranîn?','Mantiqî','Guherbar','Xelek','Mantiqî','Şert','Di bernamekirinê de, kîjan cureyê daneyê ji bo hilanîna nivîs û rêzên tîpan tê bikaranîn?','String','Integer','Float','Double','Programlama dillerinde String veri tipi, metinleri ve karakter dizilerini temsil etmek ve saklamak için kullanılır.','Di zimanên bernamekirinê de cureyê daneyê yê String ji bo temsîlkirin û hilanîna nivîsan tê bikaranîn.','Programlama dillerinde String veri tipi, metinleri ve karakter dizilerini temsil etmek ve saklamak için kullanılır.','Mantıksal (logical), programlamada doğru veya yanlış olabilen bir değeri saklamak için kullanılır. Değişken her veri türünü tutabilir, ancak hangi değerin saklanacağını veri türü belirler; döngü ve koşul ise veri türü değil, denetim yapılarıdır.','Mantiqî (logical) di bernamekirinê de ji bo hilanîna nirxekê ya ku dikare bibe rast an derew tê bikaranîn. Guherbar dikare her cureyê daneyê hilgire, lê cureyê daneyê diyar dike ka çi nirx tê hilanîn; xelek û şert jî avahiyên kontrolê ne, ne cureyên daneyê ne.','Mantıksal (logical), programlamada doğru veya yanlış olabilen bir değeri saklamak için kullanılır. Değişken her veri türünü tutabilir, ancak hangi değerin saklanacağını veri türü belirler; döngü ve koşul ise veri türü değil, denetim yapılarıdır.'),
  ('70235e02-cee3-5030-99e5-44adf8474cd2','ds_teknoloji_0073','Di bernamekirinê de, kîjan struktur ji bo hilanîna çend nirxên bêdubare û bê rêz tê bikaranîn?','Kom','Guherbar','Xelek','Kom','Şert','Di bernamekirinê de, kîjan struktura daneyê nirxan bi awayê cotên kilît û nirx radigire?','Ferheng','Lîste','Rêzik','Dar','Sözlük (Dictionary/Map), verilere hızlı erişim sağlamak amacıyla her değeri benzersiz bir anahtarla eşleştirerek saklayan veri yapısıdır.','Ferheng (Dictionary/Map) struktureke daneyê ye ku her nirxekî bi kilîteke bêhempa ve girê dide da ku gihîştina daneyê bilez bibe.','Sözlük (Dictionary/Map), verilere hızlı erişim sağlamak amacıyla her değeri benzersiz bir anahtarla eşleştirerek saklayan veri yapısıdır.','Küme (set), programlamada tekrarsız ve sırasız birden fazla değeri saklamak için kullanılır. Değişken her veri türünü tutabilir, ancak hangi değerin saklanacağını veri türü belirler; döngü ve koşul ise veri türü değil, denetim yapılarıdır.','Kom (set) di bernamekirinê de ji bo hilanîna çend nirxên bêdubare û bê rêz tê bikaranîn. Guherbar dikare her cureyê daneyê hilgire, lê cureyê daneyê diyar dike ka çi nirx tê hilanîn; xelek û şert jî avahiyên kontrolê ne, ne cureyên daneyê ne.','Küme (set), programlamada tekrarsız ve sırasız birden fazla değeri saklamak için kullanılır. Değişken her veri türünü tutabilir, ancak hangi değerin saklanacağını veri türü belirler; döngü ve koşul ise veri türü değil, denetim yapılarıdır.'),
  ('caeb03c1-5074-5ab0-9236-8a3b212ef749','ds_ziman_1101','Di malê de ji bo rûniştinê, kîjan mobîlya bi gelemperî tê bikaranîn?','Kursî','Mase','Dolab','Kursî','Nivîn','Di malê de ji bo daleqandin û hilanîna cil û bergan kîjan mobîlya tê bikaranîn?','Dolab','Mase','Kursî','Nivîn','Dolap, evde giysileri ve eşyaları düzenli biçimde saklamak için kullanılan kapaklı ve raflı mobilyadır.','Dolab mobîlyayeke bi derî û refik e ku li malê ji bo parastin û rêkûpêkkirina cil û bergan tê bikaranîn.','Dolap, evde giysileri ve eşyaları düzenli biçimde saklamak için kullanılan kapaklı ve raflı mobilyadır.','Sandalye oturmak içindir; masa, dolap ve yatak da mobilyadır ancak asıl amaçları oturmak değildir.','Kursî ji bo rûniştinê ye; mase, dolab û nivîn jî mobîlya ne lê armanca sereke ya wan rûniştin nîne.','Sandalye oturmak içindir; masa, dolap ve yatak da mobilyadır ancak asıl amaçları oturmak değildir.'),
  ('7ac9151e-6485-5edc-96b2-856c9a9ee672','ds_ziman_0080','Kîjan peyv ji bo tiştê ku em pê derî vedikin an digirin tê bikaranîn?','mifte','pirtûk','qelem','kaxez','mifte','Di dîwarê xaniyan de beşa ku ji bo ketina ronahî û hewayê ya hundir tê çêkirin çi ye?','Pencere','Derence','Ban','Stûn','Pencere, binaların duvarında odanın aydınlanmasını ve havalanmasını sağlayan açıklıktır.','Pencere vebûna di dîwarê avahiyan de ye ku hundirê odeyê ronî dike û dihêle hewa biguhere.','Pencere, binaların duvarında odanın aydınlanmasını ve havalanmasını sağlayan açıklıktır.','Anahtar, kapıları ve kilitleri açıp kapatmak için kullanılır. Kitap, kalem ve kağıt bunun için değildir.','Mifte, ji bo vekirin û girtina derî û qilifan tê bikaranîn. Pirtûk, qelem û kaxez ne ji bo vê yekê ne.','Anahtar, kapıları ve kilitleri açıp kapatmak için kullanılır. Kitap, kalem ve kağıt bunun için değildir.'),
  ('29403fe0-6951-5c14-b9bb-fe64caefc577','ds_cografya_0086','Kîjan parzemîn nêzî ji sedî 30ê axa cîhanê digire û li bakurê Okyanûsa Hindê ye?','Asya','Afrîka','Ewropa','Asya','Awistralya','Çiyayê herî bilind ê li parzemîna Asyayê û cîhanê kîjan e?','Çiyayê Everestê','Çiyayê Kilîmancaroyê','Çiyayê Elbrusê','Çiyayê Aconcaguayê','Everest Dağı, Asya kıtasındaki Himalaya sıradağlarında yer alır ve 8.848 metre ile dünyanın en yüksek zirvesidir.','Çiyayê Everestê di zincîreçiyayên Hîmalayayê de li parzemîna Asyayê cih digire û bi 8.848 metreyan lûtkeya herî bilind a cîhanê ye.','Everest Dağı, Asya kıtasındaki Himalaya sıradağlarında yer alır ve 8.848 metre ile dünyanın en yüksek zirvesidir.','Asya, Hint Okyanusu''nun kuzeyindedir ve dünya kara alanının yaklaşık %30''unu kaplar.','Asya li bakurê Okyanûsa Hindê ye û nêzî ji sedî 30ê axa cîhanê digire.','Asya, Hint Okyanusu''nun kuzeyindedir ve dünya kara alanının yaklaşık %30''unu kaplar.'),
  ('c66141c5-a330-519a-8612-40a378bb390e','ds_cand_0016','Di Newrozê de çi tê pêxistin?','Agir','Av','Ba','Agir','Erd','Cejna Newrozê mizgîniya hatina kîjan demsalê dide?','Bihar','Payîz','Zivistan','Havîn','Newroz 21 Mart''ta kutlanır ve ilkbaharın ilk günü ile doğanın uyanışı olarak kabul edilir.','Newroz di 21ê Adarê de tê pîrozkirin û wekî roja yekem a biharê û vejîna xwezayê tê qebûlkirin.','Newroz 21 Mart''ta kutlanır ve ilkbaharın ilk günü ile doğanın uyanışı olarak kabul edilir.','Newroz''da ateş yakılır; bu arınma içindir.','Di Newrozê de agir tê şewitandin; ev ji bo paqijiyê ye.','Newroz''da ateş yakılır; bu arınma içindir.'),
  ('aa741254-b723-5b45-ae05-88f53be3f46e','ds_cand_0233','Kîjan cejn bi gelemperî ji bo bîranîna Îbrahîm Pêxember tê pîrozkirin?','Cejna Qurbanê','Cejna Qurbanê','Cejna Remezanê','Newroz','Sersal','Di çanda îslamî de, Cejna Qurbanê bi kîjan îbadeta mezin a ku li bajarê Mekeyê tê bicihanîn re di heman demê de tê pîrozkirin?','Hec','Rojî','Zekat','Fitre','Kurban Bayramı, Zilhicce ayında Mekke''de yerine getirilen hac ibadeti ile aynı dönemde kutlanır.','Cejna Qurbanê di meha Zîlhiceyê de bi îbadeta hecê ya li Mekeyê re di heman demê de tê pîrozkirin.','Kurban Bayramı, Zilhicce ayında Mekke''de yerine getirilen hac ibadeti ile aynı dönemde kutlanır.','Kurban Bayramı, Hz. İbrahim''i anmak için kutlanır çünkü o kurban bayramıdır ve kurban genellikle koyun veya sığırdan verilir.','Cejna Qurbanê ji bo bîranîna Îbrahîm Pêxember tê pîrozkirin ji ber ku ew cejna qurbaniyê ye û qurbanî bi gelemperî ji pez an jî dewaran tê dayîn.','Kurban Bayramı, Hz. İbrahim''i anmak için kutlanır çünkü o kurban bayramıdır ve kurban genellikle koyun veya sığırdan verilir.'),
  ('cb957adf-37f7-570f-8c11-7aae5e0a2df5','ds_teknoloji_0124','Kîjan beşa komputerê ji bo hilanîna daneyan bi awayekî demkî dema ku bername tê xebitandin tê bikaranîn?','RAM','RAM','Hard disk','CPU','Karta torê','Kîjan parçeyê komputerê wekî mejiyê pergalê tê nasîn û fermanên bernameyan û hesabên matematîkî pêk tîne?','CPU','RAM','SSD','PSU','CPU (Merkezî İşlem Birimi), bilgisayardaki tüm mantıksal ve matematiksel işlemleri yürüten temel donanım birimidir.','CPU (Yekeya Pêvajoya Navendî) parçeyê sereke yê komputerê ye ku hemû ferman û kiryarên mantiqî û matematîkî bi rê ve dibe.','CPU (Merkezî İşlem Birimi), bilgisayardaki tüm mantıksal ve matematiksel işlemleri yürüten temel donanım birimidir.','RAM (Rastgele Erişimli Bellek), bir program çalıştırıldığında verileri geçici olarak depolamak için kullanılır. CPU''nun hızlıca erişebilmesi için verileri kısa bir süre tutar. Sabit disk kalıcı depolamadır, CPU işlemleri yapar ve ağ kartı ağ bağlantısı içindir.','RAM (Bîra Xebatê ya Rast) ji bo hilanîna daneyan bi awayekî demkî dema ku bername tê xebitandin tê bikaranîn. Ew daneyan ji bo demek kurt dihêle ku CPU zû bigihîje wan. Hard disk hilanîna daîmî ye, CPU pêvajoyê dike û karta torê ji bo torê ye.','RAM (Rastgele Erişimli Bellek), bir program çalıştırıldığında verileri geçici olarak depolamak için kullanılır. CPU''nun hızlıca erişebilmesi için verileri kısa bir süre tutar. Sabit disk kalıcı depolamadır, CPU işlemleri yapar ve ağ kartı ağ bağlantısı içindir.');

do $$
declare r record; q questions; h text; dogru_db text; ok boolean; n int; toplam int := 0; beklenen int;
  harfler text[] := array['a','b','c','d']; yeni text[]; k int; j int;
begin
  for r in select * from _yeniden loop
    select * into q from questions where id = r.id;
    if not found then update _yeniden set durum = 'yok' where id = r.id; continue; end if;
    h := lower(q.correct_option);
    dogru_db := case h when 'a' then q.option_a when 'b' then q.option_b when 'c' then q.option_c when 'd' then q.option_d end;
    ok := q.prompt = r.eski_kok and dogru_db = r.eski_dogru
      and (select array_agg(x order by x) from unnest(array[q.option_a, q.option_b, q.option_c, q.option_d]) x)
        = (select array_agg(x order by x) from unnest(array[r.e1, r.e2, r.e3, r.e4]) x);
    update _yeniden set durum = case when ok then 'uygula' else 'atla' end where id = r.id;
  end loop;
  select count(*) into beklenen from _yeniden where durum = 'uygula';
  raise notice 'alan7 yeniden yazim: uygula = %, atla = %, yok = %', beklenen,
    (select count(*) from _yeniden where durum = 'atla'), (select count(*) from _yeniden where durum = 'yok');
  for r in select * from _yeniden where durum = 'uygula' loop
    select * into q from questions where id = r.id;
    h := lower(q.correct_option);
    yeni := array[]::text[]; j := 0;
    for k in 1..4 loop
      if harfler[k] = h then yeni := yeni || r.yeni_dogru;
      else j := j + 1; yeni := yeni || (case j when 1 then r.y1 when 2 then r.y2 else r.y3 end);
      end if;
    end loop;
    update questions set prompt = r.yeni_kok, option_a = yeni[1], option_b = yeni[2], option_c = yeni[3],
      option_d = yeni[4], explanation = r.yeni_ac, explanation_ku = r.yeni_ac_ku, explanation_tr = r.yeni_ac_tr
     where id = r.id and prompt = r.eski_kok;
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'alan7 yeniden yazim: % yazilamadi', r.yerel; end if;
    toplam := toplam + n;
  end loop;
  if toplam <> beklenen then raise exception 'alan7 yeniden yazim: etkilenen % <> beklenen %', toplam, beklenen; end if;
  select count(*) into n from _yeniden y join questions qv on qv.id = y.id
   where y.durum = 'uygula' and (qv.prompt <> y.yeni_kok
     or (case lower(qv.correct_option) when 'a' then qv.option_a when 'b' then qv.option_b when 'c' then qv.option_c else qv.option_d end) <> y.yeni_dogru);
  if n > 0 then raise exception 'alan7 yeniden yazim: % soru yeni degerde degil', n; end if;
end $$;

commit;
